<?php
require __DIR__.'/includes/app.php';
$admin=json_read('admin.json',['username'=>ADMIN_USER,'password_hash'=>ADMIN_PASSWORD_HASH]);
if(!isset($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
function csrf_check(){return isset($_POST['csrf'])&&hash_equals($_SESSION['csrf']??'',$_POST['csrf']);}
function admin_redirect($msg=''){header('Location: admin.php'.($msg?'?msg='.urlencode($msg):''));exit;}
function make_slug($s){$s=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$s);$s=strtolower(preg_replace('/[^a-zA-Z0-9]+/','-',(string)$s));return trim($s,'-')?:'lesson-'.time();}
$logged=!empty($_SESSION['admin']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check()){$error='Security token expired. Refresh and try again.';}
 elseif(($_POST['action']??'')==='login'){
   $attempts=$_SESSION['login_attempts']??0;$last=$_SESSION['login_last']??0;
   if($attempts>=6&&time()-$last<900){$error='Too many attempts. Wait 15 minutes.';}
   elseif(hash_equals((string)$admin['username'],(string)($_POST['username']??''))&&password_verify((string)($_POST['password']??''),(string)$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin']=true;$_SESSION['login_attempts']=0;admin_redirect('Welcome to admin panel.');}
   else{$_SESSION['login_attempts']=$attempts+1;$_SESSION['login_last']=time();$error='Login yoki parol noto‘g‘ri.';}
 }
 elseif(($_POST['action']??'')==='logout'){session_destroy();header('Location: admin.php');exit;}
 elseif($logged&&($_POST['action']??'')==='save_article'){
   $items=json_read('articles.json',[]);$id=make_slug($_POST['id']??'');$found=false;
   $row=['id'=>$id,'category'=>in_array($_POST['category']??'',['Linux','Cisco','MikroTik','Server','Other'],true)?$_POST['category']:'Other','level'=>in_array($_POST['level']??'',['Beginner','Intermediate','Advanced'],true)?$_POST['level']:'Beginner','title'=>['uz'=>trim($_POST['title_uz']??''),'en'=>trim($_POST['title_en']??'')],'excerpt'=>['uz'=>trim($_POST['excerpt_uz']??''),'en'=>trim($_POST['excerpt_en']??'')],'body'=>['uz'=>trim($_POST['body_uz']??''),'en'=>trim($_POST['body_en']??'')]];
   if($row['title']['uz']===''||$row['title']['en']==='')$error='O‘zbekcha va inglizcha sarlavhalarni to‘ldiring.';
   else{foreach($items as $k=>$old){if($old['id']===$id){$items[$k]=$row;$found=true;break;}}if(!$found)$items[]=$row;json_write('articles.json',$items);admin_redirect('Dars saqlandi.');}
 }
 elseif($logged&&($_POST['action']??'')==='delete_article'){$id=(string)($_POST['id']??'');$items=array_values(array_filter(json_read('articles.json',[]),fn($a)=>$a['id']!==$id));json_write('articles.json',$items);admin_redirect('Dars o‘chirildi.');}
 elseif($logged&&($_POST['action']??'')==='change_password'){$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');if(!password_verify($old,(string)$admin['password_hash']))$error='Hozirgi parol noto‘g‘ri.';elseif(strlen($new)<12)$error='Yangi parol kamida 12 belgidan iborat bo‘lsin.';else{$admin['password_hash']=password_hash($new,PASSWORD_DEFAULT);json_write('admin.json',$admin);admin_redirect('Parol yangilandi.');}}
 elseif($logged&&($_POST['action']??'')==='upload_resource'){
   if(empty($_FILES['resource']['tmp_name'])||$_FILES['resource']['error']!==UPLOAD_ERR_OK)$error='Fayl tanlang.';
   elseif($_FILES['resource']['size']>MAX_UPLOAD_BYTES)$error='Fayl hajmi 8 MB dan oshmasligi kerak.';
   else{$name=$_FILES['resource']['name'];$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$allowed=['md','pdf','png','jpg','jpeg','webp','pkt'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['resource']['tmp_name']);$mimeOK=match($ext){'md'=>in_array($mime,['text/plain','text/markdown','application/octet-stream']), 'pdf'=>$mime==='application/pdf','png'=>$mime==='image/png','jpg','jpeg'=>$mime==='image/jpeg','webp'=>$mime==='image/webp','pkt'=>$mime==='application/octet-stream',default=>false};if(!in_array($ext,$allowed,true)||!$mimeOK)$error='Faqat MD, PDF, PNG, JPG yoki WEBP fayllari qabul qilinadi.';else{$safe=bin2hex(random_bytes(5)).'-'.preg_replace('/[^a-zA-Z0-9._-]/','-',basename($name));$dest=ROOT.'/uploads/'.$safe;if(move_uploaded_file($_FILES['resource']['tmp_name'],$dest)){$resources=json_read('resources.json',[]);$title=trim($_POST['resource_title']??pathinfo($name,PATHINFO_FILENAME));$resources[]=['title'=>$title,'file'=>$safe,'original'=>$name,'type'=>$ext,'created'=>date('Y-m-d')];json_write('resources.json',$resources);if($ext==='md'){$text=file_get_contents($dest);$slug=make_slug(pathinfo($name,PATHINFO_FILENAME));$items=json_read('articles.json',[]);$items[]=['id'=>$slug,'category'=>'Other','level'=>'Beginner','title'=>['uz'=>$title,'en'=>$title],'excerpt'=>['uz'=>'Markdown fayldan import qilingan maqola.','en'=>'Article imported from a Markdown file.'],'body'=>['uz'=>$text,'en'=>$text]];json_write('articles.json',$items);}admin_redirect('Fayl yuklandi. Markdown fayl maqola sifatida ham qo‘shildi.');}else $error='Faylni saqlab bo‘lmadi.';}}
 }
}
$logged=!empty($_SESSION['admin']);$all=json_read('articles.json',[]);$edit=null;if($logged&&isset($_GET['edit']))foreach($all as $a)if($a['id']===$_GET['edit'])$edit=$a;
